import React from "react";
import { render, fireEvent } from "@testing-library/react-native";
import CoinsDisplay from "../CoinsDisplay";

// Mock all problematic imports at the module level with simpler approach
jest.mock("react-native-svg", () => ({
  SvgXml: ({ testID }: any) => {
    const { View } = require("react-native");
    return <View testID={testID} />;
  },
}));

describe("CoinsDisplay", () => {
  const defaultProps = {
    coins: 25,
  };

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe("Rendering", () => {
    it("renders coin amount correctly", () => {
      const { getByText } = render(<CoinsDisplay {...defaultProps} />);

      expect(getByText("25")).toBeTruthy();
    });

    it("renders coin icon", () => {
      const { getByTestId } = render(<CoinsDisplay {...defaultProps} />);

      expect(getByTestId("coin-icon")).toBeTruthy();
    });

    it("renders as non-touchable when no onPress provided", () => {
      const { getByTestId, queryByTestId } = render(
        <CoinsDisplay {...defaultProps} />
      );

      expect(getByTestId("coins-display")).toBeTruthy();
      expect(queryByTestId("coins-display-touchable")).toBeNull();
    });

    it("renders as touchable when onPress provided", () => {
      const onPress = jest.fn();
      const { getByTestId, queryByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      expect(getByTestId("coins-display-touchable")).toBeTruthy();
      expect(queryByTestId("coins-display")).toBeTruthy();
    });

    it("displays different coin amounts correctly", () => {
      const { getByText, rerender } = render(
        <CoinsDisplay {...defaultProps} coins={0} />
      );

      expect(getByText("0")).toBeTruthy();

      rerender(<CoinsDisplay {...defaultProps} coins={100} />);
      expect(getByText("100")).toBeTruthy();

      rerender(<CoinsDisplay {...defaultProps} coins={9999} />);
      expect(getByText("9999")).toBeTruthy();
    });
  });

  describe("Touchable vs Non-Touchable Behavior", () => {
    it("shows correct layout for non-touchable display", () => {
      const { getByTestId } = render(<CoinsDisplay {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.className).toContain("flex-row items-center");
    });

    it("shows correct layout for touchable display", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      expect(coinsDisplayTouchable.props.className).toContain(
        "flex-row items-center"
      );
    });

    it("does not respond to press when not touchable", () => {
      const { getByTestId } = render(<CoinsDisplay {...defaultProps} />);

      const coinsDisplay = getByTestId("coins-display");

      // This should not throw or cause issues since it's not touchable
      expect(() => {
        fireEvent.press(coinsDisplay);
      }).not.toThrow();
    });

    it("responds to press when touchable", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplayTouchable);

      expect(onPress).toHaveBeenCalledTimes(1);
    });
  });

  describe("Button Interactions", () => {
    it("calls onPress when touchable version is pressed", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplayTouchable);

      expect(onPress).toHaveBeenCalledTimes(1);
    });

    it("handles multiple presses correctly", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");

      fireEvent.press(coinsDisplayTouchable);
      fireEvent.press(coinsDisplayTouchable);
      fireEvent.press(coinsDisplayTouchable);

      expect(onPress).toHaveBeenCalledTimes(3);
    });

    it("handles undefined onPress gracefully", () => {
      const { getByTestId } = render(
        <CoinsDisplay {...defaultProps} onPress={undefined} />
      );

      // Should render as non-touchable when onPress is undefined
      expect(getByTestId("coins-display")).toBeTruthy();
      expect(() => {
        fireEvent.press(getByTestId("coins-display"));
      }).not.toThrow();
    });
  });

  describe("Accessibility", () => {
    it("has proper accessibility properties for non-touchable version", () => {
      const { getByTestId } = render(<CoinsDisplay coins={5} />);

      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessible).toBeTruthy();
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 5 coins");
    });

    it("has proper accessibility properties for touchable version", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={10} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      expect(coinsDisplayTouchable.props.accessible).toBeTruthy();
      expect(coinsDisplayTouchable.props.accessibilityRole).toBe("button");
      expect(coinsDisplayTouchable.props.accessibilityLabel).toBe(
        "Open coin shop. You have 10 coins"
      );
    });

    it("handles singular vs plural coin text correctly", () => {
      const { getByTestId, rerender } = render(<CoinsDisplay coins={1} />);

      let coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 1 coin");

      rerender(<CoinsDisplay coins={0} />);
      coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 0 coins");

      rerender(<CoinsDisplay coins={2} />);
      coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 2 coins");
    });

    it("includes coin count in touchable accessibility label", () => {
      const onPress = jest.fn();
      const { getByTestId } = render(
        <CoinsDisplay coins={1} onPress={onPress} />
      );

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      expect(coinsDisplayTouchable.props.accessibilityLabel).toBe(
        "Open coin shop. You have 1 coin"
      );
    });
  });

  describe("Edge Cases", () => {
    it("handles zero coins correctly", () => {
      const { getByText, getByTestId } = render(<CoinsDisplay coins={0} />);

      expect(getByText("0")).toBeTruthy();
      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have 0 coins");
    });

    it("handles negative coins gracefully", () => {
      const { getByText, getByTestId } = render(<CoinsDisplay coins={-5} />);

      expect(getByText("-5")).toBeTruthy();
      const coinsDisplay = getByTestId("coins-display");
      expect(coinsDisplay.props.accessibilityLabel).toBe("You have -5 coins");
    });

    it("handles very large coin amounts", () => {
      const { getByText } = render(<CoinsDisplay coins={999999} />);

      expect(getByText("999999")).toBeTruthy();
    });

    it("handles floating point coin amounts", () => {
      const { getByText } = render(<CoinsDisplay coins={25.5} />);

      expect(getByText("25.5")).toBeTruthy();
    });

    it("handles null onPress without crashing", () => {
      expect(() => {
        render(<CoinsDisplay {...defaultProps} onPress={null as any} />);
      }).not.toThrow();
    });

    it("maintains functionality when coins prop changes rapidly", () => {
      const onPress = jest.fn();
      const { getByTestId, rerender } = render(
        <CoinsDisplay coins={10} onPress={onPress} />
      );

      // Rapidly change coin values
      for (let i = 0; i < 10; i++) {
        rerender(<CoinsDisplay coins={i * 10} onPress={onPress} />);
      }

      const coinsDisplayTouchable = getByTestId("coins-display-touchable");
      fireEvent.press(coinsDisplayTouchable);

      expect(onPress).toHaveBeenCalledTimes(1);
    });
  });

  describe("Performance", () => {
    it("updates correctly when coins prop changes", () => {
      const { getByText, rerender } = render(<CoinsDisplay coins={10} />);

      expect(getByText("10")).toBeTruthy();

      rerender(<CoinsDisplay coins={50} />);
      expect(getByText("50")).toBeTruthy();
    });

    it("updates correctly when onPress changes from undefined to defined", () => {
      const { getByTestId, queryByTestId, rerender } = render(
        <CoinsDisplay {...defaultProps} />
      );

      expect(getByTestId("coins-display")).toBeTruthy();
      expect(queryByTestId("coins-display-touchable")).toBeNull();

      const onPress = jest.fn();
      rerender(<CoinsDisplay {...defaultProps} onPress={onPress} />);

      expect(getByTestId("coins-display-touchable")).toBeTruthy();
    });

    it("updates correctly when onPress changes from defined to undefined", () => {
      const onPress = jest.fn();
      const { getByTestId, queryByTestId, rerender } = render(
        <CoinsDisplay {...defaultProps} onPress={onPress} />
      );

      expect(getByTestId("coins-display-touchable")).toBeTruthy();

      rerender(<CoinsDisplay {...defaultProps} onPress={undefined} />);

      expect(getByTestId("coins-display")).toBeTruthy();
      expect(queryByTestId("coins-display-touchable")).toBeNull();
    });

    it("handles rapid re-renders efficiently", () => {
      const { rerender } = render(<CoinsDisplay coins={10} />);

      // Simulate rapid re-renders
      for (let i = 0; i < 20; i++) {
        rerender(<CoinsDisplay coins={i % 2 === 0 ? 10 : 20} />);
      }

      // Should not throw errors
      expect(true).toBe(true);
    });

    it("handles rapid onPress callback changes efficiently", () => {
      const { rerender } = render(<CoinsDisplay {...defaultProps} />);

      // Simulate rapid onPress changes
      for (let i = 0; i < 10; i++) {
        const onPress = i % 2 === 0 ? jest.fn() : undefined;
        rerender(<CoinsDisplay {...defaultProps} onPress={onPress} />);
      }

      // Should not throw errors
      expect(true).toBe(true);
    });
  });
});
